+            return this;
+        }
+
+        public TestPhysicalPlanBuilder limit(int limit) {
+            this.limit = limit;
+            return this;
+        }
+
+        public TopNExec build() {
+            PhysicalPlan child = randomEsQueryExec(indexMode, fields.values());
+            if (aliases.isEmpty() == false) {
+                child = new EvalExec(Source.EMPTY, child, aliases);
+            }
